import React from 'react';
import './design.css';
import NavBar from "../Components/NavBar"

const DesignIdeas = () => {
  return (
    <div>
    <NavBar/>
      <div className="banner">
        <img src="/Images/Designs/banner.png" alt="Design Ideas Banner" />
      </div>
      <h1 className="design-title">DESIGN IDEAS</h1>
      <h2 className="design-title">ඇදුම් සදහා මෝස්තර සැකසීම පිළිබදව සාකච්ඡාකරන විට එය අධ්‍යනයෙහි පහසුව පිණිස පහත ආකාරයට බෙදා විමසා බලමු</h2>

      
    </div>
  );
};

export default DesignIdeas;
